;var GradientColor=function(a,b){this.getGradient=function(c){if(c>1){c=1}if(c<0){c=0}var d={R:Math.round(this.ec.R*c+this.sc.R*(1-c)),G:Math.round(this.ec.G*c+this.sc.G*(1-c)),B:Math.round(this.ec.B*c+this.sc.B*(1-c))};return d};this.getGradientRGB=function(c){return this.toHex(this.getGradient(c))};this.toRGB=function(c){if(c.charAt(0)!="#"){return null}var d={R:0,G:0,B:0};if(c.length==7){d.R=parseInt(c.substr(1,2),16);d.G=parseInt(c.substr(3,2),16);d.B=parseInt(c.substr(5,2),16)}else{d.R=parseInt(c.substr(1,1)+c.substr(1,1),16);d.G=parseInt(c.substr(2,1)+c.substr(2,1),16);d.B=parseInt(c.substr(3,1)+c.substr(3,1),16)}return d};this.toHex=function(c){var d="#";d+=("0"+c.R.toString(16)).substr(-2);d+=("0"+c.G.toString(16)).substr(-2);d+=("0"+c.B.toString(16)).substr(-2);return d};this.sc=this.toRGB(a||"#000");this.ec=this.toRGB(b||"#fff")};